        raise ValueError('uri is empty')
    if '://' not in uri:
        raise ValueError('uri must have a scheme')
    scheme, rest = uri.split('://', 1)
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()
    rest = rest.split('#')[0]
    if '?' in rest:
        path_and_authority = rest.split('?')[0]
    else:
        path_and_authority = rest
    if '/' in path_and_authority:
        authority = path_and_authority.split('/', 1)[0]
        path = '/' + path_and_authority.split('/', 1)[1]
    else:
        authority = path_and_authority
        path = '/'
    if host is not None:
        authority = host.lower()
    else:
        authority = authority.lower()
    if not authority:
        raise ValueError('uri has no host')
    if authority.startswith(':'):
        raise ValueError('uri has no host, only port')
    if ':' in authority:
        if authority.startswith('['):
            bracket_end = authority.find(']')
            if bracket_end == -1:
                raise ValueError('invalid IPv6 address')
            host_part = authority[:bracket_end + 1]
            port_part = authority[bracket_end + 1:]
            if port_part:
                if not port_part.startswith(':'):
                    raise ValueError('invalid authority')
                port_str = port_part[1:]
                if port_str == '':
                    authority = host_part
                else:
                    try:
                        port_num = int(port_str)
                    except ValueError:
                        raise ValueError('invalid port: ' + port_str)
                    if port_num <= 0 or port_num > 65535:
                        raise ValueError('invalid port number: ' + str(port_num))
                    if (scheme == 'http' and port_num == 80) or (scheme == 'https' and port_num == 443):
                        authority = host_part
                    else:
                        authority = host_part + ':' + str(port_num)
        else:
            parts = authority.split(':')
            if len(parts) > 2:
                raise ValueError('invalid authority: ' + authority)
            host_part = parts[0]
            port_str = parts[1]
            if not host_part:
                raise ValueError('uri has no host')
            if port_str == '':
                authority = host_part
            else:
                try:
                    port_num = int(port_str)
                except ValueError:
                    raise ValueError('invalid port: ' + port_str)
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('invalid port number: ' + str(port_num))
                if (scheme == 'http' and port_num == 80) or (scheme == 'https' and port_num == 443):
                    authority = host_part
                else:
                    authority = host_part + ':' + str(port_num)
    if not path:
        path = '/'
    encoded_path = urlparse.quote(urlparse.unquote(path), safe='/:@!$&\'()*+,;=')
    encoded_authority = urlparse.quote(urlparse.unquote(authority), safe=':@!$&\'()*+,;=[]')
    return scheme + '://' + encoded_authority + encoded_path
